#!/usr/bin/env bash
# Generate winhttp_shim.def for the winhttp proxy/shim DLL.
#
# The shim ships AS  winhttp.dll  next to the game (WINEDLLOVERRIDES=winhttp=n,b),
# and Proton's builtin winhttp is copied alongside as  winhttp_real.dll  (the
# forward target). Every symbol the game imports must be exported by the shim or
# the game won't load. Functions we intercept (HOOKED) are exported from our own
# object code; everything else is a zero-code loader FORWARD to the real DLL.
set -euo pipefail
cd "$(dirname "$0")"

# The COMPLETE export surface of the builtin winhttp.dll (the forward target),
# not just what the game exe's IAT binds. Other DLLs loaded into the prefix --
# notably EOSSDK-Win64-Shipping.dll -- also import from winhttp, so the shim must
# re-export EVERY builtin symbol or those imports fail to resolve at load. This
# list is the full export table of Proton's builtin winhttp.dll
# (files/lib/wine/x86_64-windows/winhttp.dll); refresh it with:
#   winedump -j export <builtin winhttp.dll> | awk '/Ordn  Name/{p=1;next} p&&/^  [0-9A-F]/{print $3}' | sort
IMPORTS="game_imports.txt"     # full builtin winhttp export surface (one name/line)
REAL_DLL="winhttp_real"        # forward target module (NO .dll suffix, DOT-FREE)
# NOTE: must be DOT-FREE. The PE loader splits a forwarder string on the LAST '.'
# to separate module from function; a name with a '.' looks like it already has
# an extension and '.dll' is NOT appended -> forward fails -> crash at load.
OUT="winhttp_shim.def"

# Functions we implement ourselves (typed trampolines w/ redirect + logging +
# capture-mode tap). Keep this list in sync with src/trampolines.cpp.
HOOKED=$(cat <<'EOF'
WinHttpConnect
WinHttpOpenRequest
WinHttpAddRequestHeaders
WinHttpSendRequest
WinHttpWriteData
WinHttpReceiveResponse
WinHttpReadData
WinHttpSetStatusCallback
WinHttpCloseHandle
EOF
)

is_hooked() { grep -qxF "$1" <<<"$HOOKED"; }

{
  echo "; AUTO-GENERATED by generate_def.sh -- do not edit by hand."
  echo "; Shim proxy for winhttp.dll. Forwards to $REAL_DLL.dll"
  echo "LIBRARY winhttp"
  echo "EXPORTS"
  while IFS= read -r fn; do
    [ -z "$fn" ] && continue
    if is_hooked "$fn"; then
      echo "    $fn"                       # exported from our code
    else
      echo "    $fn = $REAL_DLL.$fn"       # loader forwards straight through
    fi
  done < <(sort -u "$IMPORTS")
} > "$OUT"

total=$(grep -cE '^    ' "$OUT")
fwd=$(grep -cE ' = ' "$OUT")
echo "wrote $OUT: $total exports ($fwd forwarded, $((total-fwd)) hooked)"
